from pathlib import Path
P=Path(__file__).parent/'dist'
def step(name,title,body,href):return f'<a href="{href}"><span>{name}</span><strong>{title}</strong><small>{body}</small></a>'
def insert(filename,needle,html):
 p=P/filename;s=p.read_text();assert needle in s,filename;s=s.replace(needle,html+needle,1);p.write_text(s)
# Each path names a concrete handoff and links the underlying program section.
ops='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">One incident record</span><h2>Assignments connect the sections.</h2><p class="lead">Operations receives a plan, gives it to a team, and returns the result to the shared incident picture.</p><div class="handoff-chain">'+''.join([
 step('PLAN','Planning','Defines the objective and work area.','planning.html'),step('ASSIGN','Operations','Creates the task and assigns a team.','tasks.html'),step('REPORT','Field app','Sends status, observations, and hazards.','field.html'),step('REVIEW','Command','Uses the result to adjust priorities.','command.html')])+'</div></div></section>'
insert('operations.html','<section class="section operations-tools">',ops)

tasks='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">How a task connects</span><h2>The assignment carries more than instructions.</h2><div class="handoff-chain">'+''.join([
 step('INPUT','Intelligence','A lead or clue establishes a new need.','intelligence.html'),step('PLACE','Mapping','The area, route, and hazards travel with the task.','mapping.html'),step('ACTION','Field app','The team reports progress and findings.','field.html'),step('RESULT','Planning','Results change the next allocation of work.','planning.html')])+'</div><p class="handoff-note">The task stays linked to its team, map features, and narrative entries throughout that path.</p></div></section>'
insert('tasks.html','<section class="section dark"><div class="wrap"><span class="eyebrow">The operations workspace',tasks)

teams='<section class="section module-handoff"><div class="wrap team-connection-grid"><div><span class="eyebrow">A resource across modules</span><h2>The team record follows the team.</h2><p class="lead">Staffing and equipment affect readiness. The assignment establishes what the team is doing. Field status and activity become part of its history.</p></div><div class="connection-rows"><a href="logistics.html"><strong>Logistics → Teams</strong><span>Equipment, vehicles, and support reach the resource.</span></a><a href="tasks.html"><strong>Teams → Tasks</strong><span>Operations assigns a ready team to the work.</span></a><a href="field.html"><strong>Field app → Teams</strong><span>Status and observations return from the assignment.</span></a><a href="documentation.html"><strong>Teams → Documentation</strong><span>Activity logs support the incident record.</span></a></div></div></section>'
insert('teams.html','<section class="section dark"><div class="wrap"><span class="eyebrow">The operations workspace',teams)

boards='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">Status has a source and a destination</span><h2>What changes on the boards changes the picture.</h2><div class="handoff-chain">'+''.join([
 step('SOURCE','Field app','Team reports movement or task progress.','field.html'),step('VIEW','Status boards','Operations sees resource and work state.','status-boards.html'),step('DECIDE','Command','Leadership sees capacity and exceptions.','command.html'),step('RECORD','Situation report','The current picture informs a briefing or SITREP.','reporting.html')])+'</div></div></section>'
insert('status-boards.html','<section class="section dark"><div class="wrap"><span class="eyebrow">The operations workspace',boards)

command='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">Direction and feedback</span><h2>Command intent becomes field work, then returns as evidence.</h2><div class="handoff-chain">'+''.join([
 step('DIRECT','Planning','Objectives become a workable plan.','planning.html'),step('EXECUTE','Operations','Teams receive assignments and supervisors.','operations.html'),step('INFORM','Field & intelligence','Observations, clues, and status alter the picture.','intelligence.html'),step('ADJUST','Command','Priorities and resources are reviewed.','command.html')])+'</div></div></section>'
insert('command.html','<section class="ops-band">',command)

planning='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">Inputs and outputs</span><h2>Planning ties specialist information to execution.</h2><div class="planning-connection-grid"><a href="intelligence.html"><strong>Intelligence</strong><span>Subject information and clues shape the search.</span></a><a href="mapping.html"><strong>GIS &amp; SAR tools</strong><span>Segments, probability, and geography define where to work.</span></a><a href="medical-safety.html"><strong>Safety &amp; weather</strong><span>Hazards and conditions shape how and when teams deploy.</span></a><a href="logistics.html"><strong>Logistics</strong><span>Available people and equipment make a plan feasible.</span></a><div class="planning-output"><strong>Operations</strong><span>Assignments, maps, and briefings become field work.</span><a href="operations.html">Explore Operations →</a></div></div></div></section>'
insert('planning.html','<section class="section"><div class="wrap planning-close">',planning)

situation='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">The shared picture</span><h2>One update appears where it matters.</h2><div class="situation-source-grid"><div><a href="field.html">Field reports</a><a href="operations.html">Team &amp; task status</a><a href="mapping.html">Map features</a><a href="weather.html">Weather &amp; alerts</a><a href="intelligence.html">Intelligence</a></div><strong>Shared incident picture</strong><div><a href="command.html">Command decisions</a><a href="planning.html">Next assignments</a><a href="reporting.html">Briefings &amp; SITREP</a></div></div><p class="handoff-note">The same underlying records serve different roles without requiring a separate version of the incident for each section.</p></div></section>'
insert('situational-awareness.html','<section class="section"><div class="wrap situation-brief-grid">',situation)

features='<section class="section module-handoff"><div class="wrap"><span class="eyebrow">Connected by design</span><h2>Follow information across the incident.</h2><p class="lead">A clue can become a map feature, a planned assignment, a team task, a field report, and a change to the command picture. The modules each handle a part of that path.</p><div class="handoff-chain">'+''.join([step('FIND','Intelligence','Capture the lead.','intelligence.html'),step('LOCATE','Mapping','Place it in context.','mapping.html'),step('ASSIGN','Operations','Send a team.','tasks.html'),step('LEARN','Situational awareness','Bring the result back.','situational-awareness.html')])+'</div></div></section>'
insert('features.html','<section class="section screenshot-section">',features)
css='''
/* Explicit handoffs between ArcHorizon workspaces. */
.module-handoff{background:#eaf1f5}.handoff-chain{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-top:31px}.handoff-chain a{display:flex;flex-direction:column;gap:10px;min-height:190px;padding:22px;background:#fff;border:1px solid var(--line);border-top:4px solid var(--orange);text-decoration:none}.handoff-chain a:hover{border-color:var(--orange)}.handoff-chain a>span{color:#a35408;font-size:.77rem;font-weight:800;letter-spacing:.12em}.handoff-chain strong{font:700 1.18rem 'Exo 2',sans-serif}.handoff-chain small{font-size:.9rem;color:var(--muted)}.handoff-note{color:var(--muted);margin:20px 0 0}.team-connection-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:60px}.connection-rows{border-top:3px solid var(--orange)}.connection-rows a{display:grid;grid-template-columns:180px 1fr;gap:17px;padding:16px 0;border-bottom:1px solid var(--line);text-decoration:none}.connection-rows a:hover strong{text-decoration:underline}.connection-rows span{color:var(--muted)}.planning-connection-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:27px}.planning-connection-grid>a,.planning-output{display:flex;flex-direction:column;gap:9px;padding:21px;background:#fff;border:1px solid var(--line);border-top:4px solid var(--steel);text-decoration:none}.planning-connection-grid strong{font:700 1.13rem 'Exo 2',sans-serif}.planning-connection-grid span{color:var(--muted);font-size:.9rem}.planning-output{grid-column:1/-1;border-top-color:var(--orange);flex-direction:row;align-items:center;flex-wrap:wrap;gap:12px 30px}.planning-output a{color:#a45100;font-weight:750;margin-left:auto}.situation-source-grid{display:grid;grid-template-columns:1fr .75fr 1fr;gap:14px;align-items:center;margin-top:30px}.situation-source-grid>div{display:flex;flex-direction:column;gap:8px}.situation-source-grid a{display:block;padding:10px 13px;background:#fff;border:1px solid var(--line);text-decoration:none;font-weight:650}.situation-source-grid a:hover{border-color:var(--orange)}.situation-source-grid>strong{padding:32px 22px;background:var(--navy);color:#fff;text-align:center;font:700 1.35rem 'Exo 2',sans-serif;border-top:4px solid var(--orange)}body[data-theme="dark"] .module-handoff{background:#102f47}body[data-theme="dark"] .handoff-chain a,body[data-theme="dark"] .planning-connection-grid>a,body[data-theme="dark"] .planning-output,body[data-theme="dark"] .situation-source-grid a{background:#173a52;border-color:#3e6076}body[data-theme="dark"] .handoff-chain a>span,body[data-theme="dark"] .planning-output a{color:#ffb76f}@media(max-width:900px){.handoff-chain,.planning-connection-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.team-connection-grid,.situation-source-grid{grid-template-columns:1fr}.situation-source-grid>strong{padding:18px}}@media(max-width:640px){.handoff-chain,.planning-connection-grid{grid-template-columns:1fr}.handoff-chain a{min-height:0}.connection-rows a{grid-template-columns:1fr;gap:4px}.planning-output{display:flex;flex-direction:column;align-items:flex-start}.planning-output a{margin-left:0}}
'''
with (P/'styles.css').open('a') as out:out.write(css)
